// CONSULTAR API ALERTAS v2.0
// Credenciales hardcodeadas — compatible con n8n free plan.
const ALERTAS_TOKEN = 'Rd2GcVzGM3Bh8j0V+2XCriMqsdWqSSWv8mmdPyL8eMY=';
const API_URL       = 'https://deudas.sekaitech.com.pe';

let result;
try {
  result = await this.helpers.httpRequest({
    method: 'GET',
    url: API_URL + '/api/alertas/vencimientos?dias=7',
    headers: {
      'X-Alertas-Token': ALERTAS_TOKEN,
      'Accept': 'application/json'
    },
    timeout: 20000,
    json: true
  });
  // Por si el content-type no lo parsea
  if (typeof result === 'string') result = JSON.parse(result);
} catch(e) {
  return [{ json: { error: true, message: e.message } }];
}

return [{ json: result }];

// NOTIFICAR ERROR VIA EVOLUTION API
const EVOLUTION_URL      = 'https://evolution.sekaitech.com.pe';
const EVOLUTION_API_KEY  = '6mF28RqtJdPIZorVIbAaRBiKZoZr3a5t4d9jikNna7c=';
const EVOLUTION_INSTANCE = 'sekaitech';
const GROUP_JID          = '120363425809386009@g.us';

const inp  = $input.item.json;
const errorMsg = inp.message || inp.error || 'Error desconocido';
const ahora = new Date().toLocaleString('es-PE', { timeZone: 'America/Lima' });

const texto = `⚠️ *ERROR — API Alertas Control Deudas*\n🗓️ ${ahora}\n────────────────────────────────────\nNo se pudo consultar la API de vencimientos.\n\nError: ${errorMsg}\n\nRevisa los logs en Dokploy.`;

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: EVOLUTION_URL + '/message/sendText/' + EVOLUTION_INSTANCE,
    headers: {
      'apikey': EVOLUTION_API_KEY,
      'Content-Type': 'application/json'
    },
    body: { number: GROUP_JID, text: texto },
    json: true,
    timeout: 10000
  });
} catch(e) {
  // silenciar error secundario
}

return [{ json: { notified: true, error: errorMsg } }];

// =================================================================
//  PROCESAR DATOS Y PREPARAR MENSAJES (AGRUPADOS POR URGENCIA)
// =================================================================
let data = $input.first().json;

// n8n a veces anida la respuesta en .body o en .data
if (data.body && data.body.deudas !== undefined) data = data.body;
if (data.data && data.data.deudas !== undefined) data = data.data;

const deudas  = Array.isArray(data.deudas)  ? data.deudas.map(d => ({...d, _tipo: 'deuda'}))  : [];
const ordenes = Array.isArray(data.ordenes) ? data.ordenes.map(o => ({...o, _tipo: 'orden'})) : [];
const todos = [...deudas, ...ordenes];

if (todos.length === 0) {
  return [{ json: { debug_input: data, hayAlertas: "false", mensajes: [], total: 0 } }];
}

const sep = '─'.repeat(30);
const mensajes = [];

const vencHoy = todos.filter(x => x.dias_restantes <= 0);
const criticas = todos.filter(x => x.dias_restantes > 0 && x.dias_restantes <= 3);
const aviso = todos.filter(x => x.dias_restantes > 3);

let header = [
  '📋 *ALERTAS DE VENCIMIENTO*',
  '🗓️ ' + (data.generado || new Date().toLocaleString('es-PE')) + '  |  deudas.sekaitech.com.pe',
  sep,
  '📊 *Resumen de Alertas:*',
  '   • Total activas: *' + todos.length + '*'
];
if (vencHoy.length) header.push('   • 🔴 Vencidas/Hoy: *' + vencHoy.length + '*');
if (criticas.length) header.push('   • 🟠 Críticas (≤3d): *' + criticas.length + '*');
if (aviso.length) header.push('   • 🟡 Próximas (>3d): *' + aviso.length + '*');
mensajes.push(header.join('\n'));

const buildItem = (item, i) => {
  let res = [];
  res.push('');
  if (item._tipo === 'deuda') {
    res.push(` *${i + 1}. [DEUDA] ${item.cliente}*`);
    res.push(`   📋 Concepto: ${item.descripcion}`);
    res.push(`   💰 Pendiente: *${item.monto}*`);
    res.push(`   👤 Resp: ${item.responsable || 'No asignado'}`);
    let diasStr = item.dias_restantes < 0 ? `Hace ${Math.abs(item.dias_restantes)} día(s)` : 
                  item.dias_restantes === 0 ? `¡HOY!` : 
                  `Faltan ${item.dias_restantes} días`;
    res.push(`   📅 Vence: *${item.fecha_vencimiento}* (${diasStr})`);
  } else {
    res.push(` *${i + 1}. [ORDEN] OC #${item.orden_compra}*`);
    res.push(`   🏢 Entidad: ${item.entidad}`);
    res.push(`   🔧 Item: ${item.producto_servicio}`);
    res.push(`   💰 Monto: *${item.monto}*`);
    res.push(`   📊 Estado: ${item.estado_seguimiento}`);
    res.push(`   👤 Resp: ${item.responsable || 'No asignado'}`);
    let diasStr = item.dias_restantes < 0 ? `Hace ${Math.abs(item.dias_restantes)} día(s)` : 
                  item.dias_restantes === 0 ? `¡HOY!` : 
                  `Faltan ${item.dias_restantes} días`;
    res.push(`   📅 Límite: *${item.fecha_limite_pago}* (${diasStr})`);
  }
  return res.join('\n');
};

if (vencHoy.length > 0) {
  let bloque = ['🔴 *VENCIDAS O VENCEN HOY (Acción Inmediata)*', sep];
  vencHoy.forEach((x, i) => bloque.push(buildItem(x, i)));
  mensajes.push(bloque.join('\n'));
}

if (criticas.length > 0) {
  let bloque = ['🟠 *CRÍTICAS (Próximas a vencer 1-3 días)*', sep];
  criticas.forEach((x, i) => bloque.push(buildItem(x, i)));
  mensajes.push(bloque.join('\n'));
}

if (aviso.length > 0) {
  let bloque = ['🟡 *AVISO DE VENCIMIENTO (> 3 días)*', sep];
  aviso.forEach((x, i) => bloque.push(buildItem(x, i)));
  mensajes.push(bloque.join('\n'));
}

return [{ json: { hayAlertas: "true", mensajes, total: todos.length } }];

// ENVIAR VIA EVOLUTION API → GRUPO WHATSAPP
const EVOLUTION_URL      = 'https://evolution.sekaitech.com.pe';
const EVOLUTION_API_KEY  = '6mF28RqtJdPIZorVIbAaRBiKZoZr3a5t4d9jikNna7c=';
const EVOLUTION_INSTANCE = 'sekaitech';
const GROUP_JID          = '120363425809386009@g.us';

let results = [];

// Iteramos sobre TODOS los mensajes generados para asegurar que ninguno se pierda
for (const item of $input.all()) {
  const mensaje = item.json.mensaje || '';
  if (!mensaje) continue;

  try {
    const r = await this.helpers.httpRequest({
      method: 'POST',
      url: EVOLUTION_URL + '/message/sendText/' + EVOLUTION_INSTANCE,
      headers: {
        'apikey': EVOLUTION_API_KEY,
        'Content-Type': 'application/json'
      },
      body: {
        number: GROUP_JID,
        text: mensaje
      },
      json: true,
      timeout: 15000
    });
    results.push({ json: { success: true, key: r.key } });

    // Retraso de seguridad interno para no saturar WhatsApp
    await new Promise(resolve => setTimeout(resolve, 1500));
  } catch(e) {
    results.push({ json: { success: false, error: e.message } });
  }
}

return results;
